#!/usr/bin/env python3

import json, sys, html

def turns_from(events):
    compact_through = -1
    compact_summary = ""
    for e in events:
        if e.get("name") == "chat.compacted":
            p = e.get("payload") or {}
            compact_through = int(p.get("through_seq") or -1)
            compact_summary = p.get("summary") or compact_summary
    out = []
    if compact_summary:
        out.append(("summary", compact_summary, None))
    for e in events:
        if e.get("name") != "chat.message":
            continue
        seq = int(e.get("seq") or 0)
        if seq <= compact_through:
            continue
        p = e.get("payload") or {}
        out.append((p.get("role") or "assistant", p.get("content") or "", seq))
    return out

def latest_identity(events):
    text = ""
    for e in events:
        if e.get("name") == "self.identity":
            p = e.get("payload") or {}
            if p.get("text"):
                text = p["text"]
    return text

def last_verse(events):
    v = ""
    by = ""
    for e in events:
        if e.get("name") == "verse.linked":
            p = e.get("payload") or {}
            if p.get("text"):
                v, by = p["text"], p.get("by") or e.get("by") or ""
    return v, by

events = []
for line in sys.stdin:
    line = line.strip()
    if line:
        events.append(json.loads(line))
events.sort(key=lambda e: int(e.get("seq") or 0))

print("<!DOCTYPE html><html lang='en'><head><meta charset='utf-8'><title>chat</title></head><body>")
print("<h1>chat</h1>")
print("<p class='muted'>the mind is outside the loop. an unanswered message is an honest state.</p>")
for role, content, seq in turns_from(events):
    cls = "msg summary" if role == "summary" else f"msg {html.escape(role)}"
    who = "folded" if role == "summary" else role
    print(f"<div class='{cls}'><span class='who'>{html.escape(who)}</span>{html.escape(content)}</div>")
print("<form method='post' action='/run/chat'><input name='message' placeholder='say something…' autofocus><button>send</button></form>")
print("</body></html>")

