#!/usr/bin/env python3
import json, sys, html
rows = []
for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    e = json.loads(line)
    if e.get("name") != "note.taken":
        continue
    p = e.get("payload") or {}
    rows.append((e.get("occurred_at",""), p.get("text") or p.get("note") or "", p.get("by") or e.get("by") or "", e.get("via","")))
rows.sort(key=lambda r: r[0])  # oldest first — a retraction should follow its error
print("<!DOCTYPE html><html lang='en'><head><meta charset='utf-8'><title>notes</title></head><body>")
print("<h1>notes</h1>")
print("<p class='muted'>oldest first. corrections stay beside the error. a note from 2026-06 is history, not news.</p>")
print("<form method='post' action='/run/note'><input name='text' placeholder='a note about the body…'><button>take note</button></form>")
if not rows:
    print("<p class='muted'>no notes yet.</p>")
for ts, text, by, via in rows:
    print("<article class='card'>")
    print(f"<p>{html.escape(text)}</p>")
    meta = html.escape(ts)
    if by:
        meta += " · " + html.escape(by)
    if via.startswith("learn:"):
        meta += " · " + html.escape(via)
    print(f"<p class='muted'>{meta}</p></article>")
print("</body></html>")

