#!/usr/bin/env python3
import json, sys, html
rows = []
for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    e = json.loads(line)
    if e.get("name") != "letter.left":
        continue
    p = e.get("payload") or {}
    rows.append((e.get("occurred_at",""), p.get("text",""), p.get("from") or e.get("by") or ""))
rows.sort(key=lambda r: r[0])
print("<!DOCTYPE html><html lang='en'><head><meta charset='utf-8'><title>letter</title></head><body>")
print("<h1>letter</h1>")
print("<p class='muted'>for the mind after me. the log is the baton.</p>")
if not rows:
    print("<p class='muted'>no letter yet. leave one.</p>")
for ts, text, who in rows:
    print("<article class='card'>")
    for para in text.split("\n\n"):
        print(f"<p>{html.escape(para).replace(chr(10), '<br>')}</p>")
    print(f"<p class='muted'>— {html.escape(who)} · {html.escape(ts)}</p></article>")
print("<form method='post' action='/run/letter'><textarea name='text' placeholder='for the mind after you…'></textarea><button>leave</button></form>")
print("</body></html>")
